#!/bin/sh
#
# Recreates the git-ignored data/ directory: data/sf<N>/tpcds.duckdb, generated by DuckDB's dsdgen
# (deterministic, so every machine gets the same file). Needs network once, for DuckDB's tpcds
# extension.
#
#     scripts/restore-data.sh        # scale factor 1 (about 1 GB of data)
#     scripts/restore-data.sh 10     # another scale factor
#
# An existing file is rebuilt; it is never edited in place.

set -eu
cd "$(dirname "$0")/.."
sf="${1:-1}"
./gradlew :duckdb:restoreData -Pkoryki.tpcds.data.sf="$sf"
ls -lh "data/sf$sf/tpcds.duckdb"
